<script setup lang="ts">
import {ref,computed,watch,onUnmounted} from 'vue'
import {Plus,X,MapPin} from 'lucide-vue-next'
import {useLocal} from '../stores/local'
import {canonical,type Document} from '../domain/local-contract'
import type {CompanionProfile} from './contract'
import {worldDraft,validateCompanionWorld,type CompanionWorld} from './world-context'
const props=defineProps<{profile:Document<CompanionProfile>}>(),emit=defineEmits<{saved:[Document<CompanionProfile>]}>(),store=useLocal(),base=ref(props.profile),form=ref(worldDraft(props.profile.value.world)),busy=ref(false),error=ref(''),conflict=ref(false),status=ref('')
const dirty=computed(()=>canonical(form.value)!==canonical(worldDraft(base.value.value.world)))
let intent:{operationId:string;revision:number;value:CompanionProfile}|null=null
let disposed=false
onUnmounted(()=>disposed=true)
watch(()=>props.profile,row=>{if(!dirty.value&&!busy.value){base.value=row;form.value=worldDraft(row.value.world);intent=null}},{flush:'sync'})
function reset(){base.value=props.profile;form.value=worldDraft(base.value.value.world);intent=null;conflict.value=false;error.value='';status.value=''}
async function recheck(){const vault=store.vault;if(!vault||busy.value)return;busy.value=true;error.value='';try{const row=await vault.read<CompanionProfile>(props.profile.id);if(!row||row.kind!=='companion'||row.value.deleted||row.value.identityId!==base.value.value.identityId)throw Error('伴侣档案已失效');if(store.vault!==vault||!vault.unlocked)return;base.value=row;intent=null;conflict.value=false;status.value='已载入当前档案，你的输入保留。'}catch(e){error.value=(e as Error).message}finally{busy.value=false}}
async function save(clear=false){const vault=store.vault,row=base.value;if(!vault||busy.value||conflict.value)return;busy.value=true;error.value='';status.value='';const value={...row.value};if(clear)delete value.world;else {const world:CompanionWorld={...row.value.world,schema:'companion-world-v1',...form.value,people:form.value.people.map(person=>({...person})),updatedAt:new Date().toISOString()};try{validateCompanionWorld(world)}catch(e){error.value=(e as Error).message;busy.value=false;return}value.world=world}
  const normalized=(profile:CompanionProfile)=>({...profile,...(profile.world?{world:{...profile.world,updatedAt:''}}:{})})
  const same=intent&&intent.revision===row.revision&&canonical(normalized(intent.value))===canonical(normalized(value))
  if(!same)intent={operationId:crypto.randomUUID(),revision:row.revision,value}
  const request=intent!
  const active=()=>!disposed&&store.vault===vault&&vault.unlocked
  const accepted=(saved:Document<CompanionProfile>)=>{base.value=saved;form.value=worldDraft(saved.value.world);intent=null;conflict.value=false;status.value=clear?'世界设置已清空。':'世界设置已保存。';emit('saved',saved)}
  try{await vault.commit(request.operationId,'companion',row.id,request.revision,request.value);if(active()){const saved=await vault.read<CompanionProfile>(row.id);if(saved&&canonical(saved.value)===canonical(request.value))accepted(saved);else throw Error('保存结果暂时无法确认，输入仍保留。')}}catch(e){if(active()){try{const saved=await vault.read<CompanionProfile>(row.id);if(saved&&saved.kind==='companion'&&canonical(saved.value)===canonical(request.value)){accepted(saved);return}}catch{}conflict.value=(e as {code?:string}).code==='REVISION_CONFLICT';error.value=conflict.value?'档案已在别处更新。你的输入保留，请载入当前档案后再保存。':(e as Error).message}}finally{busy.value=false}
}
</script>
<template><section class="world-panel"><div class="world-heading"><MapPin :size="20"/><h2>{{base.value.world?.name||'TA 的世界'}}</h2></div><form class="final-card-form" @submit.prevent="save()"><fieldset :disabled="busy"><label>世界名称<input v-model="form.name" maxlength="120"></label><label>世界设定<textarea v-model="form.description" maxlength="6000" rows="4"></textarea></label><div class="world-two"><label>TA 所在的地方<input v-model="form.currentPlace" maxlength="120"></label><label>生活作息<textarea v-model="form.dayPlan" maxlength="4000" rows="3"></textarea></label></div><div class="world-people"><h3>周围的人</h3><article v-for="(person,index) in form.people" :key="index"><div><label>人物名字<input v-model="person.name" maxlength="120" required></label><label>人物设定<textarea v-model="person.description" maxlength="2000" rows="2"></textarea></label></div><button type="button" class="final-icon-button" :aria-label="'移除人物 '+(person.name||String(index+1))" @click="form.people.splice(index,1)"><X :size="18"/></button></article><button type="button" :disabled="form.people.length>=10" @click="form.people.push({name:'',description:''})"><Plus :size="18"/>添加人物</button></div><label class="world-share"><input v-model="form.shareWithChat" type="checkbox">用于下一次伴侣对话</label><div class="world-actions"><button class="final-primary" :disabled="conflict">{{busy?'正在保存…':'保存世界'}}</button><button type="button" @click="reset">恢复已保存设置</button><button v-if="base.value.world" type="button" :disabled="conflict" @click="save(true)">清空世界</button></div></fieldset></form><p v-if="error" class="final-error" role="alert">{{error}}</p><button v-if="conflict" :disabled="busy" @click="recheck">载入当前档案并保留输入</button><p v-if="status" class="final-subtle" role="status">{{status}}</p></section></template>
<style scoped>
.world-panel{max-width:840px}.world-heading{display:flex;gap:10px;align-items:center;margin-bottom:20px}.world-heading h2{font-family:var(--font-serif);font-weight:400;overflow-wrap:anywhere}.world-heading svg{flex:none;color:var(--accent)}.final-card-form{max-width:none}.world-panel fieldset{border:0;padding:0;margin:0;min-width:0;display:grid;gap:20px}.world-two{display:grid;grid-template-columns:1fr 1fr;gap:18px}.world-people{display:grid;gap:14px}.world-people h3{font-weight:500;font-size:16px}.world-people article{display:flex;align-items:start;gap:12px}.world-people article>div{display:grid;gap:12px;flex:1;min-width:0}.world-people .final-icon-button{flex:none}.world-share{display:flex;gap:12px;align-items:center;min-height:44px;cursor:pointer}.world-share input{width:22px;height:22px;flex:none}.world-actions{display:flex;gap:10px;flex-wrap:wrap}.world-actions button{overflow-wrap:anywhere}@media(max-width:600px){.world-two{grid-template-columns:1fr}.world-panel .final-card-form{padding:16px}}
</style>
